scripts:
/*********************************************************
 * 초기화
 ******************************************************** */
function fn_egov_init(){
	// 첫 입력란에 포커스..
	document.articleForm.searchCnd.focus();
}

/*********************************************************
 * 페이징 처리 함수
 ******************************************************** */
function fn_egov_select_linkPage(pageNo){
	document.articleForm.pageIndex.value = pageNo;
	document.articleForm.action = "/board/boardList.do";
	document.articleForm.submit();
}
/*********************************************************
 * 조회 처리 함수
 ******************************************************** */
function fn_egov_search_article(){
	document.articleForm.pageIndex.value = 1;
	document.articleForm.submit();
}
/* ********************************************************
 * 상세회면 처리 함수
 ******************************************************** */
function fn_egov_inquire_articledetail(boardTypeNum, boardNum) {
	// 사이트 키값(siteId) 셋팅.
	document.subForm.boardTypeNum.value = boardTypeNum;
	document.subForm.boardNum.value = boardNum;
	document.subForm.submit();
}

function downFile(dirName, fileName, originName){
	window.open("/board/fileDown2.do?dirName="+dirName+"&fileName="+fileName+"&originName="+encodeURI(originName)+"");
}
